/**
 * Fold a raw city string into a lookup key: lowercase, accents stripped,
 * anything that is not a letter or digit collapsed to a single space.
 * "Kirti Nagar, Delhi" and "GK - 1" become "kirti nagar delhi" and "gk 1".
 */
export function normalisePlaceKey(raw) {
  if (raw == null) return '';
  return String(raw)
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();
}

/**
 * Resolve a raw city string.
 *
 * Returns { status, key, label, coord?, note? } where status is:
 *   'mapped'     — we have a coordinate and it will be drawn
 *   'region'     — a state or direction, too broad to be a point
 *   'outside'    — a real place, but not in India
 *   'unrecorded' — the field was blank
 *   'nonplace'   — the field holds something that is not a place
 *   'unknown'    — a name we simply have no coordinate for
 *
 * Every status except 'mapped' is surfaced in the list beside the map.
 */
export function lookupPlace(raw) {
  const key = normalisePlaceKey(raw);
  const label = String(raw ?? '').trim();

  if (!key) return { status: 'unrecorded', key: '', label: 'City not recorded' };

  const unmappable = UNMAPPABLE_PLACES[key];
  if (unmappable) {
    return { status: unmappable.kind, key, label: unmappable.label };
  }

  const resolved = CITY_ALIASES[key] || key;
  const coord = CITY_COORDS[resolved];
  if (coord) {
    return {
      status: 'mapped',
      key: resolved,
      label: coord.name,
      coord,
      note: coord.note,
    };
  }

  // A purely numeric field is a phone number or an ID that landed in the city
  // column, not a place. Calling that "unknown city" would be misleading.
  if (/^\d+$/.test(key.replace(/\s/g, ''))) {
    return { status: 'nonplace', key, label: label || key };
  }

  return { status: 'unknown', key, label: label || key };
}

/** Number of places with a coordinate — shown in the map footnote. */
export const MAPPED_CITY_COUNT = Object.keys(CITY_COORDS).length;
